5382:     fn required_rejects_malformed_decision_schema_and_selector_output() {
5383:         let ci = valid_ci_workflow();
5384:         let run = required_body(&ci);
5385:         let base = CI_REQUIRED_BASE;
5386:         let head = CI_REQUIRED_SHA;
