5388:         let (live, main) = required_pr_api(base, head, "open", "synchronize");
5389:         let replies = [
5390:             ApiReply {
5391:                 request: "api repos/owner/repo/pulls/124",
5392:                 body: serde_json::to_vec(&live).unwrap(),
5393:                 exit: 0,
5394:             },
5395:             ApiReply {
5396:                 request: "api repos/owner/repo/git/ref/heads/main",
5397:                 body: serde_json::to_vec(&main).unwrap(),
5398:                 exit: 0,
5399:             },
5400:         ];
5401:         for decision in [
5402:             Value::Null,
5403:             json!({"schema_version":2}),
5404:             json!({"schema_version":1,"mode":"unknown"}),
5405:         ] {
5406:             let result = run_required_result(
5407:                 run,
5408:                 &required_results("full"),
5409:                 &decision,
5410:                 "pull_request",
5411:                 &event,
5412:                 "refs/pull/124/merge",
5413:                 &replies,
5414:             );
5415:             assert!(
5416:                 !result.output.status.success(),
5417:                 "accepted malformed selector: {decision}"
5418:             );
5419:         }
5420:         let light = required_decision("lightweight", base, head, true);
5421:         let mut invalid_reason = light.clone();
5422:         invalid_reason["reason_code"] = json!("lightweight");
5423:         assert!(!run_required_result(
5424:             run,
5425:             &required_results("lightweight"),
5426:             &invalid_reason,
5427:             "pull_request",
5428:             &event,
5429:             "refs/pull/124/merge",
5430:             &replies
5431:         )
5432:         .output
5433:         .status
5434:         .success());
5435:     }
